def parse_json(stdout):
    """stdout must carry exactly one JSON object; tolerate leading/trailing text lines around it."""
    try:
        return json.loads(stdout)
    except Exception:
        pass
    i, j = stdout.find("{"), stdout.rfind("}")
    if i >= 0 and j > i:
        try:
            return json.loads(stdout[i:j + 1])
        except Exception:
            return None
    return None


def failed_predicates(obj):
    """Names of the failing predicates the instrument reported (see interface note in the header)."""
    names = set()

    def take(x):
        if isinstance(x, str) and x.strip():
            names.add(re.split(r"[\s:@(\[]", x.strip(), 1)[0])
        elif isinstance(x, dict):
            for k in ("predicate", "name", "error", "id"):
                if isinstance(x.get(k), str):
                    names.add(x[k].strip())
                    break
        elif isinstance(x, list):
            for i in x:
                take(i)

    if isinstance(obj, dict):
        for key in ("error", "errors", "failed", "failed_predicates", "failures", "rejects"):
            if key in obj:
                take(obj[key])
    return names


def count(obj, key):
    if not isinstance(obj, dict):
        return None
    if key in obj:
        return obj[key]
    return (obj.get("counts") or {}).get(key)


def run_check(fixture, *extra):
    cmd = ["python3", str(CHECK), str(fixture), "--psl", str(PSL), *extra]
    r = subprocess.run(cmd, capture_output=True, text=True, cwd=str(REPO))
    return r.returncode, r.stdout, r.stderr, parse_json(r.stdout), " ".join(cmd)


class CheckAuditBase(unittest.TestCase):
    maxDiff = None

    def _ctx(self, rc, out, err, cmd):
        return f"\n$ {cmd}\nexit={rc}\n--- stdout ---\n{out[-2000:]}\n--- stderr ---\n{err[-2000:]}"

    def assert_pass(self, fixture, *extra):
        rc, out, err, obj, cmd = run_check(fixture, *extra)
        ctx = self._ctx(rc, out, err, cmd)
        self.assertEqual(rc, 0, "expected exit 0" + ctx)
        self.assertIsInstance(obj, dict, "stdout must be a JSON object" + ctx)
        self.assertEqual(failed_predicates(obj), set(), "exit 0 must report no failed predicate" + ctx)
        return obj, ctx

    def assert_fail(self, fixture, token, *extra):
        rc, out, err, obj, cmd = run_check(fixture, *extra)
        ctx = self._ctx(rc, out, err, cmd)
        self.assertEqual(rc, 1, "expected exit 1" + ctx)
        self.assertIsInstance(obj, dict, "stdout must be a JSON object" + ctx)
        failed = failed_predicates(obj)
        self.assertTrue(failed, "exit 1 must name at least one failed predicate" + ctx)
        if token is not None:
            self.assertIn(token, failed, f"failed predicates {sorted(failed)} lack {token!r}" + ctx)
        return obj, ctx

    def assert_count(self, obj, ctx, key, expected):
        got = count(obj, key)
        self.assertIsNotNone(got, f"JSON lacks count field {key!r}" + ctx)
        self.assertEqual(got, expected, f"{key} expected {expected}, got {got}" + ctx)


