# ---------------------------------------------------------------- REQ-007 (Card commits never touch the audited dirs)
class TestREQ007Replay(unittest.TestCase):
    # based_on: REQ-007
    maxDiff = None

    def _run_replay(self, cwd):
        r = subprocess.run(["bash", str(REPLAY)], capture_output=True, text=True, cwd=str(cwd))
        ctx = f"\n$ (cd {cwd} && bash {REPLAY})\nexit={r.returncode}\n--- stdout ---\n{r.stdout[-2000:]}\n--- stderr ---\n{r.stderr[-2000:]}"
        return r.returncode, r.stdout, parse_json(r.stdout), ctx

    def test_AC_007_a_replay_card_commits_exit0_touching_zero(self):
        # AC-007-a: every commit carrying a `Card: CARD-xx` footer, replayed as verify_commit.py --range <sha>^..<sha>
        # --card cards/<xx>.yaml → exit 0, card_commits_touching_audited_dirs 0.  Run from <D> so cards/<xx>.yaml resolves.
        rc, out, obj, ctx = self._run_replay(D)
        self.assertEqual(rc, 0, "expected exit 0" + ctx)
        self.assertIsInstance(obj, dict, "stdout must be a JSON object" + ctx)
        self.assertEqual(count(obj, "card_commits_touching_audited_dirs"), 0, ctx)

    def test_AC_007_b_card_commit_touching_skills_exit1_whitelist_overflow(self):
        # AC-007-b: a Card commit whose diff modifies a file under plugins/sdlc/skills/** → exit 1, error whitelist_overflow.
        # Synthetic twin: a temp git repo on a feature branch, cards/ copied from <D>, one seed commit, then one commit with
        # footer `Card: CARD-01` that modifies plugins/sdlc/skills/twin/SKILL.md (forbidden by CARD-01.forbidden_files).
        tmp = Path(tempfile.mkdtemp(prefix="ring-audit-twin-"))
        try:
            env = dict(os.environ, GIT_AUTHOR_NAME="l5", GIT_AUTHOR_EMAIL="l5@test", GIT_COMMITTER_NAME="l5",
                       GIT_COMMITTER_EMAIL="l5@test")

            def git(*a):
                r = subprocess.run(["git", "-c", "commit.gpgsign=false", "-c", "user.name=l5", "-c", "user.email=l5@test",
                                    *a], cwd=str(tmp), capture_output=True, text=True, env=env)
                self.assertEqual(r.returncode, 0, f"git {' '.join(a)} failed: {r.stderr}")
                return r.stdout

            git("init", "-q", "-b", "feature/ring-audit-twin")
            shutil.copytree(D / "cards", tmp / "cards")
            skill = tmp / "plugins/sdlc/skills/twin/SKILL.md"
            skill.parent.mkdir(parents=True)
            skill.write_text("# twin\nversion: 1\n", encoding="utf-8")
            git("add", "-A")
            git("commit", "-q", "-m", "chore(sdlc): seed twin repo (no card footer)")
            skill.write_text("# twin\nversion: 2\n", encoding="utf-8")
            git("add", "-A")
            git("commit", "-q", "-m", "fix(sdlc): twin edits an audited skill\n\nCard: CARD-01\n")

            rc, out, obj, ctx = self._run_replay(tmp)
            self.assertEqual(rc, 1, "expected exit 1" + ctx)
            failed = failed_predicates(obj) if isinstance(obj, dict) else set()
            self.assertTrue("whitelist_overflow" in failed or "whitelist_overflow" in out,
                            "whitelist_overflow must be reported" + ctx)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)


